import { useEffect, useMemo, useState, type ChangeEvent, type ReactNode } from "react";
import {
  Activity, ArrowLeft, ArrowRight, BarChart3, Boxes, CheckCircle2, ChevronRight,
  Camera, Check, CircleDollarSign, Clock3, CreditCard, Crop, Edit3, Eye, FileSearch, Gauge, Globe2, Heart,
  Home, Image as ImageIcon, LayoutDashboard, Menu, Package, PackageSearch,
  ImagePlus, MapPin, Minus, Plus, RotateCw, Save, Search, Settings, ShieldCheck,
  ShoppingBag, Sparkles, Store, Tag, Trash2, Truck, Upload, Users, Wallet, X, ZoomIn,
} from "lucide-react";
import { customers, orders, products, visitorsByDay, type DemoProduct } from "./data";

const asset = (path: string) => `${import.meta.env.BASE_URL}${path}`;
const money = (value: number) => new Intl.NumberFormat("pt-BR", { style: "currency", currency: "BRL" }).format(value);
const routeNow = () => (location.hash.replace(/^#/, "") || "/").split("?")[0];
function go(path: string) { location.hash = path; window.scrollTo({ top: 0, behavior: "smooth" }); }

export default function App() {
  const [route, setRoute] = useState(routeNow);
  useEffect(() => { const listener = () => setRoute(routeNow()); addEventListener("hashchange", listener); return () => removeEventListener("hashchange", listener); }, []);
  return route.startsWith("/dashboard") ? <Dashboard route={route} /> : <Storefront route={route} />;
}

function Storefront({ route }: { route: string }) {
  const [menu, setMenu] = useState(false); const [cart, setCart] = useState(false); const [checkout, setCheckout] = useState(false); const [cartItems, setCartItems] = useState<DemoProduct[]>([]); const [notice, setNotice] = useState("");
  const product = route.startsWith("/produto/") ? products.find((p) => p.handle === route.split("/")[2]) : undefined;
  const add = (item: DemoProduct) => { setCartItems((old) => [...old, item]); setNotice(`${item.title} foi adicionado ao carrinho.`); setTimeout(() => setNotice(""), 3500); };
  return <div className="min-h-screen bg-background text-foreground">
    <header className="sticky top-0 z-40 border-b border-border/60 bg-background/95 backdrop-blur"><div className="mx-auto flex max-w-6xl items-center justify-between px-4 py-3"><button onClick={() => go("/")}><img src={asset("logo-imastore.png")} className="h-14 w-auto" alt="Foto Ímãs Store" /></button>
      <nav className="hidden items-center gap-6 md:flex"><a href="#produtos" className="nav-link">Produtos</a><a href="#tematicos" className="nav-link">Temáticos</a><a href="#como-funciona" className="nav-link">Como funciona</a></nav>
      <div className="flex items-center gap-2 md:gap-3"><button onClick={() => setMenu(true)} className="icon-button md:hidden" aria-label="Abrir menu"><Menu className="h-5 w-5" /></button><button onClick={() => go("/acompanhar-pedido")} className="hidden items-center gap-2 rounded-full border border-border/60 bg-card px-4 py-1.5 text-sm font-semibold text-foreground/80 transition hover:border-accent/40 hover:text-accent md:flex"><PackageSearch className="h-4 w-4" /> Acompanhar pedido</button><button onClick={() => go("/acompanhar-pedido")} className="icon-button md:hidden" aria-label="Acompanhar pedido"><PackageSearch className="h-4 w-4" /></button><button onClick={() => setCart(true)} className="icon-button relative" aria-label="Carrinho"><ShoppingBag className="h-5 w-5" />{cartItems.length > 0 && <span className="absolute -right-1 -top-1 flex h-5 w-5 items-center justify-center rounded-full bg-accent text-[10px] font-bold text-white">{cartItems.length}</span>}</button></div></div></header>
    {menu && <Overlay onClose={() => setMenu(false)} side="left"><div className="p-5"><img src={asset("logo-imastore.png")} className="h-16" alt="Foto Ímãs Store" /><div className="mt-6 space-y-2"><MenuItem icon={Home} label="Página inicial" onClick={() => { go("/"); setMenu(false); }} /><MenuItem icon={Sparkles} label="Produtos personalizados" onClick={() => { go("/"); setMenu(false); setTimeout(() => document.getElementById("produtos")?.scrollIntoView(), 80); }} /><MenuItem icon={Heart} label="Combos temáticos" onClick={() => { go("/"); setMenu(false); setTimeout(() => document.getElementById("tematicos")?.scrollIntoView(), 80); }} /><MenuItem icon={PackageSearch} label="Como funciona" onClick={() => { go("/"); setMenu(false); setTimeout(() => document.getElementById("como-funciona")?.scrollIntoView(), 80); }} /><MenuItem icon={PackageSearch} label="Acompanhar meu pedido" featured onClick={() => { go("/acompanhar-pedido"); setMenu(false); }} /></div></div></Overlay>}
    {cart && <Overlay onClose={() => setCart(false)}><div className="flex h-full flex-col p-5"><h2 className="font-display text-2xl font-bold text-primary">Seu carrinho</h2><p className="mt-1 text-sm text-muted-foreground">{cartItems.length === 0 ? "Seu carrinho está vazio" : `${cartItems.length} item${cartItems.length !== 1 ? "s" : ""} no carrinho`}</p><div className="mt-6 flex-1 space-y-3 overflow-y-auto">{cartItems.length === 0 ? <Empty icon={ShoppingBag} title="Carrinho vazio" text="Adicione ímãs para começar 💖" /> : cartItems.map((item, index) => <div key={`${item.id}-${index}`} className="cart-line flex gap-3 rounded-2xl bg-secondary/50 p-3"><img src={asset(item.image)} className="h-16 w-16 rounded-xl object-cover" /><div className="min-w-0 flex-1"><p className="truncate font-bold text-primary">{item.title}</p><p className="text-xs text-muted-foreground">Quantidade: 1</p><p className="font-bold text-accent">{money(item.price)}</p></div><button onClick={() => setCartItems((old) => old.filter((_, i) => i !== index))} className="icon-button h-8 w-8" aria-label="Remover item"><Trash2 className="h-4 w-4" /></button></div>)}</div>{cartItems.length > 0 && <div className="border-t pt-4"><div className="mb-4 flex justify-between font-bold"><span>Total dos produtos</span><span className="text-xl text-accent">{money(cartItems.reduce((sum, item) => sum + item.price, 0))}</span></div><button onClick={() => { setCart(false); setCheckout(true); }} className="primary-button w-full"><Wallet className="mr-2 h-4 w-4" /> Pagar com Mercado Pago</button></div>}</div></Overlay>}
    {checkout && <CheckoutDemo total={cartItems.reduce((sum, item) => sum + item.price, 0)} onClose={() => setCheckout(false)} onFinish={() => { setCheckout(false); setCartItems([]); setNotice("Pedido FIS-1049 criado com sucesso!"); setTimeout(() => setNotice(""), 4000); }} />}
    {notice && <div className="fixed bottom-5 left-1/2 z-[70] -translate-x-1/2 rounded-2xl bg-primary px-5 py-3 text-sm font-bold text-primary-foreground shadow-xl">{notice}</div>}
    {product ? <ProductDetail product={product} onAdd={add} /> : route === "/acompanhar-pedido" || route === "/acompanhar" ? <TrackingDemo /> : <HomePage onAdd={add} />}
    <footer className="border-t border-border/60 bg-secondary/40"><div className="mx-auto max-w-6xl px-4 py-10 text-center"><p className="font-display text-xl font-bold text-primary">Foto Ímãs Store</p><p className="mt-1 text-sm text-muted-foreground">Seu momento, sempre por perto.</p><button onClick={() => go("/acompanhar-pedido")} className="mt-4 inline-flex text-sm font-semibold text-accent hover:underline">Acompanhar meu pedido</button><p className="mt-6 flex items-center justify-center gap-1.5 text-xs text-muted-foreground">Feito com <Heart className="h-3.5 w-3.5 fill-accent text-accent" /> para guardar suas memórias</p><p className="mt-2 text-xs text-muted-foreground">© {new Date().getFullYear()} Foto Ímãs Store. Todos os direitos reservados.</p></div></footer>
  </div>;
}

function HomePage({ onAdd }: { onAdd: (product: DemoProduct) => void }) {
  const personalized = products.filter((p) => p.photoCount > 0); const themes = products.filter((p) => p.photoCount === 0);
  return <main className="page-enter"><section style={{ background: "var(--gradient-hero)" }}><div className="mx-auto grid max-w-6xl items-center gap-8 px-4 py-14 md:grid-cols-2 md:py-20"><div className="hero-copy text-center md:text-left"><span className="inline-flex items-center gap-1.5 rounded-full bg-card px-4 py-1.5 text-sm font-semibold text-accent shadow-[var(--shadow-soft)]"><Sparkles className="h-4 w-4" /> Personalize momentos</span><h1 className="mt-5 font-display text-4xl font-bold leading-tight text-primary sm:text-5xl md:text-6xl">Transforme suas <span className="text-accent">fotos</span> em ímãs que você ama</h1><p className="mx-auto mt-4 max-w-md text-lg text-foreground/70 md:mx-0">Ímãs personalizados, combos e kits temáticos para deixar suas memórias sempre por perto. ✨</p><div className="mt-7 flex flex-wrap justify-center gap-3 md:justify-start"><a href="#produtos" className="primary-button">Ver produtos</a><a href="#tematicos" className="secondary-button">Combos temáticos</a></div></div><img src={asset("hero.jpg")} className="hero-image w-full rounded-[2rem] object-cover shadow-[var(--shadow-soft)]" alt="Geladeira cheia de ímãs com fotos de memórias" /></div></section>
    <section className="mx-auto max-w-6xl px-4 py-12"><div className="grid gap-4 sm:grid-cols-3"><Benefit icon={ImageIcon} title="Alta qualidade" text="Impressão nítida e cores vivas que duram." /><Benefit icon={Sparkles} title="100% personalizado" text="Você envia e ajusta o recorte de cada foto pelo próprio site." /><Benefit icon={Truck} title="Entrega para todo Brasil" text="Suas memórias chegam com carinho até você." /></div></section>
    <ProductSection id="produtos" eyebrow="" title="Ímãs personalizados" description="Escolha a unidade ou economize com os combos." products={personalized} onAdd={onAdd} />
    <ProductSection id="tematicos" eyebrow="" title="Combos temáticos" description="Para fãs de verdade: Harry Potter, Friends, Stranger Things e mais." products={themes} onAdd={onAdd} shaded />
    <section id="como-funciona" className="mx-auto max-w-6xl scroll-mt-20 px-4 py-14"><div className="mb-8 text-center"><h2 className="section-title">Como funciona</h2><p className="mt-2 text-muted-foreground">Em 3 passinhos simples.</p></div><div className="grid gap-6 sm:grid-cols-3">{[[Heart,"Escolha","Selecione o produto ou combo ideal para você."],[Upload,"Envie suas fotos","Envie, visualize e recorte cada foto antes de pagar."],[Truck,"Receba","Produzimos com carinho e enviamos até a sua casa."]].map(([Icon,title,text], i) => <div key={String(title)} className="relative overflow-hidden rounded-3xl border border-border/60 bg-card p-6 shadow-[var(--shadow-card)]"><span className="absolute right-4 top-3 select-none font-display text-7xl font-bold leading-none text-accent/10">{i+1}</span><span className="mb-3 flex h-10 w-10 items-center justify-center rounded-2xl bg-accent/15"><Icon className="h-5 w-5 text-accent" /></span><h3 className="font-display text-lg font-semibold text-primary">{String(title)}</h3><p className="mt-1 text-sm text-muted-foreground">{String(text)}</p></div>)}</div></section>
    <section className="bg-secondary/35 py-14"><div className="mx-auto grid max-w-6xl gap-8 px-4 md:grid-cols-[1fr_1.15fr]"><div><h2 className="font-display text-3xl font-bold text-primary sm:text-4xl">Ímãs de geladeira feitos com as suas memórias</h2><p className="mt-4 leading-relaxed text-foreground/75">Crie ímãs personalizados com fotos da família, viagens, pets, aniversários e momentos especiais. Você visualiza o enquadramento no próprio site, ajusta o recorte e envia a quantidade exata de imagens de cada combo.</p><p className="mt-3 leading-relaxed text-foreground/75">Depois da compra, o pedido e as fotos ficam organizados pelo mesmo código. Antes de iniciarmos a produção, ainda é possível substituir uma imagem pela página de acompanhamento.</p></div><div><h2 className="font-display text-2xl font-bold text-primary">Dúvidas frequentes</h2><div className="mt-4 space-y-3">{[["Como envio as fotos dos ímãs?","Na página do produto, selecione as imagens, confira a prévia e ajuste o recorte antes de adicionar ao carrinho."],["Quantas fotos preciso enviar?","A quantidade é automática: uma foto por ímã personalizado. O site só libera o pagamento quando todas estiverem prontas."],["Posso trocar uma foto depois do pagamento?","Sim. Consulte o pedido com o código e o e-mail da compra. A substituição fica disponível até a produção começar."],["Vocês entregam em todo o Brasil?","Sim. O frete e o prazo disponíveis para seu endereço aparecem após informar o CEP no checkout."]].map(([question,answer]) => <details key={question} className="group rounded-2xl border border-border/60 bg-card p-4 shadow-[var(--shadow-card)]"><summary className="cursor-pointer list-none font-semibold text-primary">{question}</summary><p className="mt-2 text-sm leading-relaxed text-muted-foreground">{answer}</p></details>)}</div></div></div></section>
  </main>;
}

function ProductSection({ id, eyebrow, title, description, products: list, onAdd, shaded = false }: { id: string; eyebrow: string; title: string; description: string; products: DemoProduct[]; onAdd: (p: DemoProduct) => void; shaded?: boolean }) {
  return <section id={id} className={`scroll-mt-20 ${shaded ? "bg-secondary/40 py-12" : "py-8"}`}><div className="mx-auto max-w-6xl px-4"><div className="mb-6 text-center">{eyebrow && <p className="section-eyebrow">{eyebrow}</p>}<h2 className="section-title">{title}</h2><p className="mt-2 text-muted-foreground">{description}</p></div><div className="grid grid-cols-1 gap-5 sm:grid-cols-2 lg:grid-cols-3">{list.map((product) => <ProductCard key={product.id} product={product} onAdd={onAdd} />)}</div></div></section>;
}
function ProductCard({ product, onAdd }: { product: DemoProduct; onAdd: (p: DemoProduct) => void }) { const handleAdd = () => product.photoCount > 0 ? go(`/produto/${product.handle}`) : onAdd(product); return <article className="group flex flex-col overflow-hidden rounded-3xl border border-border/60 bg-card shadow-[var(--shadow-card)] transition hover:-translate-y-1"><button onClick={() => go(`/produto/${product.handle}`)} className="relative aspect-square overflow-hidden bg-secondary/40 text-left"><img src={asset(product.image)} className="h-full w-full object-cover transition duration-300 group-hover:scale-105" alt={product.title} />{product.compareAt && <span className="absolute right-3 top-3 rounded-full bg-accent px-3 py-1 text-xs font-bold text-white">Oferta</span>}</button><div className="flex flex-1 flex-col p-4"><button onClick={() => go(`/produto/${product.handle}`)} className="text-left"><h3 className="line-clamp-2 font-display text-lg font-bold text-primary">{product.title}</h3><p className="mt-1 line-clamp-2 text-sm text-muted-foreground">{product.description}</p></button><div className="mt-auto flex items-end justify-between gap-2 pt-4"><div>{product.compareAt && <span className="block text-xs text-muted-foreground line-through">{money(product.compareAt)}</span>}<span className="font-display text-xl font-bold text-accent">{money(product.price)}</span></div><button onClick={handleAdd} className="icon-button bg-accent text-white" aria-label={product.photoCount > 0 ? "Escolher fotos" : "Adicionar ao carrinho"}><ShoppingBag className="h-5 w-5" /></button></div></div></article>; }

function ProductDetail({ product, onAdd }: { product: DemoProduct; onAdd: (p: DemoProduct) => void }) {
  const [photosOpen, setPhotosOpen] = useState(false);
  const add = () => product.photoCount > 0 ? setPhotosOpen(true) : onAdd(product);
  return <main className="page-enter mx-auto max-w-5xl px-4 py-10"><button onClick={() => go("/")} className="inline-flex items-center gap-2 text-sm font-bold text-muted-foreground transition hover:text-accent"><ArrowLeft className="h-4 w-4" /> Voltar à loja</button><div className="mt-6 grid gap-8 md:grid-cols-2"><div className="overflow-hidden rounded-[2rem] border bg-secondary/40 shadow-[var(--shadow-soft)]"><img src={asset(product.image)} className="aspect-square w-full object-cover transition duration-500 hover:scale-[1.03]" /></div><div className="flex flex-col"><span className="w-fit rounded-full bg-secondary px-3 py-1 text-xs font-bold text-primary">{product.category}</span><h1 className="mt-4 font-display text-3xl font-bold text-primary sm:text-4xl">{product.title}</h1><div className="mt-4 flex items-end gap-3"><p className="font-display text-3xl font-bold text-accent">{money(product.price)}</p>{product.compareAt && <p className="pb-1 text-lg text-muted-foreground line-through">{money(product.compareAt)}</p>}</div><p className="mt-5 leading-7 text-foreground/80">{product.description}</p><div className="mt-6 space-y-2 rounded-2xl bg-secondary/40 p-4 text-sm text-foreground/80">{["Impressão de alta qualidade", "Acabamento resistente", product.photoCount > 0 ? `${product.photoCount} foto${product.photoCount !== 1 ? "s" : ""} com prévia e recorte` : "Arte temática pronta para produção"].map((text) => <p key={text} className="flex items-center gap-2"><Check className="h-4 w-4 text-teal" /> {text}</p>)}</div><button onClick={add} className="primary-button mt-7 w-full">{product.photoCount > 0 ? <Camera className="mr-2 h-5 w-5" /> : <ShoppingBag className="mr-2 h-5 w-5" />}{product.photoCount > 0 ? "Escolher fotos e adicionar" : "Adicionar ao carrinho"}</button></div></div>{photosOpen && <PhotoConfiguratorDemo product={product} onClose={() => setPhotosOpen(false)} onSave={() => { setPhotosOpen(false); onAdd(product); }} />}</main>;
}

function PhotoConfiguratorDemo({ product, onClose, onSave }: { product: DemoProduct; onClose: () => void; onSave: () => void }) {
  const [slots, setSlots] = useState<string[]>(() => Array.from({ length: product.photoCount }, () => ""));
  const [editing, setEditing] = useState<number | null>(null);
  const [zoom, setZoom] = useState(1);
  const [rotation, setRotation] = useState(0);
  const ready = slots.filter(Boolean).length;
  const addFiles = (event: ChangeEvent<HTMLInputElement>, target?: number) => {
    const selected = Array.from(event.target.files || []).filter((file) => file.type.startsWith("image/"));
    if (!selected.length) return;
    const urls = selected.map((file) => URL.createObjectURL(file));
    setSlots((current) => {
      const next = [...current];
      if (target !== undefined) next[target] = urls[0];
      else {
        const empty = next.map((value, index) => value ? -1 : index).filter((index) => index >= 0);
        urls.slice(0, empty.length).forEach((url, index) => { next[empty[index]] = url; });
      }
      return next;
    });
    event.target.value = "";
  };
  const fillDemo = () => setSlots(Array.from({ length: product.photoCount }, (_, index) => `${asset(product.image)}?demo=${index}`));
  return <Modal onClose={onClose} title="Escolha suas fotos">
    <div className="modal-step-enter">
      <p className="text-sm text-muted-foreground">{product.title}: envie exatamente {product.photoCount} foto{product.photoCount !== 1 ? "s" : ""}. Você poderá conferir e ajustar cada recorte.</p>
      <div className="mt-5 flex flex-wrap items-center justify-between gap-3 rounded-2xl bg-secondary/50 p-4"><div><p className="font-bold text-primary">{ready} de {product.photoCount} fotos prontas</p><p className="text-xs text-muted-foreground">JPG, PNG ou WEBP. A demonstração mantém os arquivos apenas no seu navegador.</p></div><div className="flex flex-wrap gap-2"><button onClick={fillDemo} className="secondary-button py-2"><Sparkles className="mr-2 h-4 w-4" /> Preencher exemplo</button><label className="secondary-button cursor-pointer py-2"><ImagePlus className="mr-2 h-4 w-4" /> Selecionar fotos<input type="file" accept="image/*" multiple className="sr-only" onChange={addFiles} /></label></div></div>
      <div className="mt-5 grid grid-cols-2 gap-3 sm:grid-cols-3 md:grid-cols-4">{slots.map((preview, index) => <div key={index} className="photo-slot overflow-hidden rounded-2xl border bg-card"><div className="relative aspect-square bg-secondary/50">{preview ? <img src={preview} className="h-full w-full object-cover" alt={`Foto ${index + 1}`} /> : <div className="flex h-full items-center justify-center text-muted-foreground"><Camera className="h-7 w-7" /></div>}<span className="absolute left-2 top-2 flex h-6 min-w-6 items-center justify-center rounded-full bg-card px-1 text-xs font-bold shadow">{index + 1}</span>{preview && <span className="absolute right-2 top-2 flex h-6 w-6 items-center justify-center rounded-full bg-teal text-white shadow"><Check className="h-3.5 w-3.5" /></span>}</div><div className="grid grid-cols-2 gap-1 p-2"><button disabled={!preview} onClick={() => { setEditing(index); setZoom(1); setRotation(0); }} className="rounded-lg px-2 py-1.5 text-xs font-bold transition hover:bg-secondary disabled:opacity-35"><Crop className="mr-1 inline h-3.5 w-3.5" /> Ajustar</button><label className="cursor-pointer rounded-lg px-2 py-1.5 text-center text-xs font-bold transition hover:bg-secondary">Trocar<input type="file" accept="image/*" className="sr-only" onChange={(event) => addFiles(event, index)} /></label></div></div>)}</div>
      <button disabled={ready !== product.photoCount} onClick={onSave} className="primary-button mt-5 w-full disabled:cursor-not-allowed disabled:opacity-45">Confirmar {product.photoCount} foto{product.photoCount !== 1 ? "s" : ""}</button>
    </div>
    {editing !== null && <div className="absolute inset-0 z-20 flex items-center justify-center rounded-3xl bg-background p-5"><div className="w-full"><div className="flex items-center justify-between"><div><h3 className="font-display text-xl font-bold text-primary">Ajustar foto {editing + 1}</h3><p className="text-sm text-muted-foreground">Arraste os controles até encontrar o melhor enquadramento.</p></div><button onClick={() => setEditing(null)} className="icon-button"><X className="h-4 w-4" /></button></div><div className="crop-stage mx-auto mt-5 aspect-square max-w-sm overflow-hidden rounded-3xl bg-primary/10"><img src={slots[editing]} className="h-full w-full object-cover transition-transform duration-200" style={{ transform: `scale(${zoom}) rotate(${rotation}deg)` }} /></div><div className="mx-auto mt-5 max-w-sm space-y-4"><label className="block"><span className="flex items-center justify-between text-sm font-bold"><span><ZoomIn className="mr-1 inline h-4 w-4" /> Zoom</span><span>{Math.round(zoom * 100)}%</span></span><input type="range" min="1" max="2" step="0.05" value={zoom} onChange={(event) => setZoom(Number(event.target.value))} className="mt-2 w-full accent-[var(--accent)]" /></label><div className="flex justify-center gap-2"><button onClick={() => setRotation((value) => value - 90)} className="secondary-button py-2"><RotateCw className="mr-2 h-4 w-4 -scale-x-100" /> Girar</button><button onClick={() => { setZoom(1); setRotation(0); }} className="secondary-button py-2"><Minus className="mr-2 h-4 w-4" /> Restaurar</button></div><button onClick={() => setEditing(null)} className="primary-button w-full"><Check className="mr-2 h-4 w-4" /> Usar este recorte</button></div></div></div>}
  </Modal>;
}

function CheckoutDemo({ total, onClose, onFinish }: { total: number; onClose: () => void; onFinish: () => void }) {
  const [cep, setCep] = useState("");
  const [addressReady, setAddressReady] = useState(false);
  const [shipping, setShipping] = useState<"" | "pac" | "sedex">("");
  const [paying, setPaying] = useState(false);
  const formatCep = (value: string) => value.replace(/\D/g, "").slice(0, 8).replace(/^(\d{5})(\d)/, "$1-$2");
  const changeCep = (value: string) => { const formatted = formatCep(value); setCep(formatted); setAddressReady(formatted.replace(/\D/g, "").length === 8); setShipping(""); };
  const finish = () => { setPaying(true); setTimeout(onFinish, 1100); };
  const freight = shipping === "sedex" ? 27.9 : shipping === "pac" ? 18.9 : 0;
  return <Modal onClose={onClose} title="Finalizar pedido">
    <div className="modal-step-enter space-y-5"><div className="rounded-2xl border border-accent/25 bg-accent/10 p-4"><p className="flex items-center gap-2 font-bold text-primary"><CreditCard className="h-5 w-5 text-accent" /> Pagamento pelo Mercado Pago</p><p className="mt-1 text-sm text-muted-foreground">Pix, cartão ou boleto — simulação visual, sem cobrança.</p></div><div className="grid gap-3 sm:grid-cols-2"><FormField label="Nome completo" value="Ana Carolina Demo" /><FormField label="WhatsApp" value="(11) 99999-2026" /><label className="block sm:col-span-2"><span className="text-sm font-bold">E-mail</span><input className="demo-input mt-1" defaultValue="ana.demo@email.com" /></label></div><div><div className="mb-3 flex items-center gap-2"><MapPin className="h-5 w-5 text-accent" /><p className="font-display text-lg font-bold text-primary">Endereço de entrega</p></div><label className="block"><span className="text-sm font-bold">CEP</span><input className="demo-input mt-1" value={cep} onChange={(event) => changeCep(event.target.value)} placeholder="00000-000" inputMode="numeric" /></label>{addressReady && <div className="address-reveal mt-3 grid gap-3 sm:grid-cols-2"><FormField label="Rua" value="Avenida Paulista" /><FormField label="Número" value="1578" /><FormField label="Bairro" value="Bela Vista" /><FormField label="Cidade" value="São Paulo" /><label className="block"><span className="text-sm font-bold">Estado</span><select className="demo-input mt-1" defaultValue="SP"><option>SP</option><option>RJ</option><option>MG</option><option>PR</option></select></label><FormField label="Complemento" value="Apto. 42" /></div>}</div>{addressReady && <div className="rounded-2xl border p-4"><p className="font-bold text-primary">Opções de entrega</p><div className="mt-3 grid gap-2 sm:grid-cols-2"><button onClick={() => setShipping("pac")} className={`rounded-2xl border p-3 text-left transition ${shipping === "pac" ? "border-accent bg-accent/10" : "hover:border-accent/40"}`}><span className="block font-bold">Econômico · 7 dias</span><span className="text-sm text-accent">R$ 18,90</span></button><button onClick={() => setShipping("sedex")} className={`rounded-2xl border p-3 text-left transition ${shipping === "sedex" ? "border-accent bg-accent/10" : "hover:border-accent/40"}`}><span className="block font-bold">Expresso · 3 dias</span><span className="text-sm text-accent">R$ 27,90</span></button></div><button onClick={() => setShipping("pac")} className="secondary-button mt-3 w-full"><Truck className="mr-2 h-4 w-4" /> {shipping ? "Calcular novamente" : "Calcular frete"}</button></div>}<div className="rounded-2xl bg-secondary/50 p-4"><div className="flex justify-between text-sm"><span>Produtos</span><span>{money(total)}</span></div><div className="mt-1 flex justify-between text-sm"><span>Frete</span><span>{shipping ? money(freight) : "A calcular"}</span></div><div className="mt-3 flex justify-between border-t pt-3 font-bold"><span>Total</span><span className="text-xl text-accent">{money(total + freight)}</span></div></div><button disabled={!shipping || paying} onClick={finish} className="primary-button w-full disabled:cursor-not-allowed disabled:opacity-45">{paying ? <><RotateCw className="mr-2 h-4 w-4 animate-spin" /> Criando pedido fictício...</> : <><Wallet className="mr-2 h-4 w-4" /> Pagar com Mercado Pago</>}</button></div>
  </Modal>;
}

function TrackingDemo() { const [searched, setSearched] = useState(false); const steps = ["Pagamento aprovado", "Fotos recebidas", "Em produção", "Enviado", "Entregue"]; return <main className="mx-auto max-w-3xl px-4 py-12"><div className="text-center"><span className="mx-auto flex h-14 w-14 items-center justify-center rounded-2xl bg-accent/15 text-accent"><PackageSearch className="h-7 w-7" /></span><h1 className="mt-4 font-display text-3xl font-bold text-primary">Acompanhar pedido</h1><p className="mt-2 text-sm text-muted-foreground">Digite o código recebido após a compra e o mesmo e-mail usado no pagamento.</p></div><div className="mx-auto mt-8 grid max-w-xl gap-4 rounded-3xl border border-border/60 bg-card p-6 shadow-[var(--shadow-card)] sm:grid-cols-2"><label className="text-sm font-bold">Código do pedido<input defaultValue="FIS-1046" className="demo-input mt-2" /></label><label className="text-sm font-bold">E-mail da compra<input defaultValue="camila@email.com" className="demo-input mt-2" /></label><button onClick={() => setSearched(true)} className="primary-button sm:col-span-2"><Search className="mr-2 h-4 w-4" /> Consultar pedido</button></div>{searched && <section className="mt-6 space-y-5 rounded-3xl border border-border/60 bg-card p-6 shadow-[var(--shadow-card)]"><div className="flex flex-wrap items-start justify-between gap-3"><div><p className="text-xs uppercase tracking-wide text-muted-foreground">Pedido</p><h2 className="font-display text-xl font-bold text-primary">FIS-1046</h2><p className="text-xs text-muted-foreground">Criado em 18/08/2026 às 14:32</p></div><span className="rounded-full bg-accent/15 px-3 py-1 text-sm font-bold text-accent">Enviado</span></div><div className="space-y-3">{steps.map((step, index) => <div key={step} className="flex items-center gap-3"><span className={`flex h-8 w-8 items-center justify-center rounded-full ${index <= 3 ? "bg-teal/25 text-teal-foreground" : "bg-secondary text-muted-foreground"}`}>{index <= 3 ? <Check className="h-4 w-4" /> : <Clock3 className="h-4 w-4" />}</span><span className={index <= 3 ? "font-semibold" : "text-muted-foreground"}>{step}</span></div>)}</div><div className="grid gap-4 rounded-2xl bg-secondary/40 p-4 text-sm sm:grid-cols-2"><div><p className="text-xs text-muted-foreground">Entrega</p><p className="font-semibold">Transportadora Nacional — Econômico</p><p className="text-xs text-muted-foreground">Destino: São Paulo — SP</p></div><div className="sm:text-right"><p className="text-xs text-muted-foreground">Total</p><p className="font-display text-lg font-bold text-primary">R$ 169,80</p></div></div><div className="flex flex-wrap items-center justify-between gap-3 rounded-2xl bg-teal/15 p-4"><div><p className="flex items-center gap-2 font-semibold text-primary"><Truck className="h-4 w-4" /> Código de rastreio</p><p className="font-mono text-sm">BR123456789XX</p></div><button className="secondary-button">Rastrear transportadora</button></div><div><p className="mb-2 text-xs font-semibold uppercase tracking-wide text-muted-foreground">Itens</p><div className="flex justify-between border-t border-border/50 py-2 text-sm"><span>Combo 24 Ímãs Personalizados</span><span className="font-semibold">×1</span></div></div></section>}</main>; }

const dashboardNav = [
  ["/dashboard", "Visão geral", LayoutDashboard], ["/dashboard/pedidos", "Pedidos", ShoppingBag],
  ["/dashboard/produtos", "Produtos", Package], ["/dashboard/clientes", "Clientes", Users],
  ["/dashboard/analytics", "Analytics", BarChart3], ["/dashboard/seo", "SEO", Search],
  ["/dashboard/configuracoes", "Configurações", Settings],
] as const;

function Dashboard({ route }: { route: string }) {
  const [mobile, setMobile] = useState(false); const [saved, setSaved] = useState("");
  const page = route === "/dashboard" || route === "/dashboard/" ? "overview" : route.split("/")[2];
  const content = page === "pedidos" ? <OrdersView /> : page === "produtos" ? <ProductsView onNotice={setSaved} /> : page === "clientes" ? <CustomersView /> : page === "analytics" ? <AnalyticsView /> : page === "seo" ? <SeoView onNotice={setSaved} /> : page === "configuracoes" ? <SettingsView /> : <OverviewView />;
  return <div className="min-h-screen bg-background"><div className="lg:grid lg:grid-cols-[16rem_1fr]"><aside className="sticky top-0 hidden h-screen border-r bg-card/60 p-4 lg:block"><DashboardBrand /><DashboardLinks route={route} /></aside><div className="min-w-0"><header className="sticky top-0 z-30 flex items-center justify-between border-b bg-background/90 px-4 py-3 backdrop-blur lg:px-8"><div className="flex items-center gap-2"><button onClick={() => setMobile(true)} className="icon-button lg:hidden"><Menu className="h-5 w-5" /></button><span className="rounded-full bg-secondary px-3 py-1.5 text-xs font-bold text-primary">Painel administrativo</span></div><button onClick={() => go("/")} className="secondary-button py-2"><Store className="mr-2 h-4 w-4" /> Ver loja</button></header><main className="px-4 py-7 lg:px-8">{content}</main></div></div>{mobile && <Overlay onClose={() => setMobile(false)} side="left"><div className="p-4"><DashboardBrand /><DashboardLinks route={route} onNavigate={() => setMobile(false)} /></div></Overlay>}{saved && <div className="fixed bottom-5 left-1/2 z-[70] -translate-x-1/2 rounded-2xl bg-primary px-5 py-3 text-sm font-bold text-primary-foreground shadow-xl">{saved}</div>}</div>;
}
function DashboardBrand() { return <button onClick={() => go("/dashboard")} className="mx-auto mb-6 flex flex-col items-center"><img src={asset("logo-imastore.png")} className="h-14" /><span className="mt-1 text-xs font-bold text-muted-foreground">Painel de gestão</span></button>; }
function DashboardLinks({ route, onNavigate }: { route: string; onNavigate?: () => void }) { return <nav className="space-y-1">{dashboardNav.map(([path,label,Icon]) => { const active = path === "/dashboard" ? route === path || route === `${path}/` : route.startsWith(path); return <button key={path} onClick={() => { go(path); onNavigate?.(); }} className={`flex w-full items-center gap-3 rounded-xl px-3 py-3 text-left text-sm font-bold transition ${active ? "bg-accent text-white" : "text-foreground/70 hover:bg-secondary"}`}><Icon className="h-4.5 w-4.5" />{label}</button>; })}<div className="my-3 border-t" /><button onClick={() => go("/")} className="flex w-full items-center gap-3 rounded-xl px-3 py-3 text-sm font-bold text-foreground/70 hover:bg-secondary"><Store className="h-4.5 w-4.5" /> Voltar à loja</button></nav>; }

function PageTitle({ title, text, action }: { title: string; text: string; action?: ReactNode }) { return <div className="mb-6 flex flex-col gap-3 sm:flex-row sm:items-end sm:justify-between"><div><h1 className="font-display text-3xl font-bold text-primary">{title}</h1><p className="mt-1 text-sm text-muted-foreground">{text}</p></div>{action}</div>; }
function OverviewView() { const revenue = orders.filter((o) => o.payment === "Pago").reduce((n,o) => n+o.total,0); return <><PageTitle title="Visão geral" text="Resumo fictício da operação da loja." /><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Stat label="Receita no período" value={money(revenue)} icon={CircleDollarSign} tone="accent" hint="+18,4% vs. período anterior" /><Stat label="Pedidos" value="48" icon={ShoppingBag} tone="teal" hint="12 aguardando produção" /><Stat label="Clientes" value="39" icon={Users} tone="lilac" hint="8 clientes recorrentes" /><Stat label="Produtos ativos" value={String(products.length)} icon={Boxes} tone="yellow" hint="3 produtos em oferta" /></div><div className="mt-5 grid gap-5 xl:grid-cols-[1.35fr_0.65fr]"><Panel title="Receita e pedidos"><MiniChart /></Panel><Panel title="Pedidos por status"><div className="space-y-4">{[["Entregue",18,75],["Enviado",11,58],["Em produção",12,50],["Aguardando",7,30]].map(([name,value,width]) => <div key={String(name)}><div className="flex justify-between text-sm"><span className="font-bold">{name}</span><span>{value}</span></div><div className="mt-1 h-2 rounded-full bg-secondary"><div className="h-full rounded-full bg-accent" style={{ width: `${width}%` }} /></div></div>)}</div></Panel></div><div className="mt-5"><Panel title="Pedidos recentes"><OrdersTable compact /></Panel></div></>; }
function OrdersView() {
  const [list, setList] = useState([...orders]);
  const [editing, setEditing] = useState<(typeof orders)[number] | null>(null);
  const update = (field: "payment" | "status", value: string) => editing && setEditing({ ...editing, [field]: value });
  return <><PageTitle title="Pedidos" text="Gerencie pagamentos, produção e entrega com dados fictícios." action={<button onClick={() => alert("Relatório fictício preparado para apresentação.")} className="secondary-button"><FileSearch className="mr-2 h-4 w-4" /> Exportar relatório</button>} /><Panel title="Todos os pedidos"><OrdersTable list={list} actions onEdit={setEditing} onDelete={(id) => setList((current) => current.filter((order) => order.id !== id))} /></Panel>{editing && <Modal title={`Editar ${editing.id}`} onClose={() => setEditing(null)}><div className="space-y-4"><FormField label="Cliente" value={editing.customer} /><FormField label="E-mail" value={editing.email} /><label className="block"><span className="text-sm font-bold">Pagamento</span><select className="demo-input mt-1" value={editing.payment} onChange={(event) => update("payment", event.target.value)}><option>Pago</option><option>Pendente</option><option>Cancelado</option></select></label><label className="block"><span className="text-sm font-bold">Produção e envio</span><select className="demo-input mt-1" value={editing.status} onChange={(event) => update("status", event.target.value)}><option>Aguardando</option><option>Em produção</option><option>A enviar</option><option>Enviado</option><option>Entregue</option></select></label><FormField label="Código de rastreio" value="DEMO-BR123456789" /><button onClick={() => { setList((current) => current.map((order) => order.id === editing.id ? editing : order)); setEditing(null); }} className="primary-button w-full"><Save className="mr-2 h-4 w-4" /> Salvar alteração fictícia</button></div></Modal>}</>;
}
function OrdersTable({ compact = false, list = orders, actions = false, onEdit, onDelete }: { compact?: boolean; list?: typeof orders; actions?: boolean; onEdit?: (order: (typeof orders)[number]) => void; onDelete?: (id: string) => void }) { return <div className="overflow-x-auto"><table className="w-full min-w-[760px] text-sm"><thead><tr className="border-b text-left text-xs uppercase text-muted-foreground"><th className="py-3">Pedido</th><th>Cliente</th><th>Data</th><th>Pagamento</th><th>Produção</th><th className="text-right">Total</th>{actions && <th className="text-right">Ações</th>}</tr></thead><tbody>{list.slice(0, compact ? 5 : list.length).map((o) => <tr key={o.id} className="border-b border-border/50 transition hover:bg-secondary/30 last:border-0"><td className="py-3 font-bold text-primary">{o.id}</td><td><p className="font-semibold">{o.customer}</p><p className="text-xs text-muted-foreground">{o.email}</p></td><td>{o.date}</td><td><Status value={o.payment} /></td><td><Status value={o.status} /></td><td className="text-right font-bold">{money(o.total)}</td>{actions && <td><div className="flex justify-end gap-1"><button onClick={() => onEdit?.(o)} className="icon-button h-8 w-8" aria-label="Editar"><Edit3 className="h-3.5 w-3.5" /></button><button onClick={() => onDelete?.(o.id)} className="icon-button h-8 w-8 text-destructive" aria-label="Excluir"><Trash2 className="h-3.5 w-3.5" /></button></div></td>}</tr>)}</tbody></table></div>; }
function ProductsView({ onNotice }: { onNotice: (s: string) => void }) {
  const [catalog, setCatalog] = useState([...products]);
  const [editing, setEditing] = useState<DemoProduct | null>(null);
  const [adding, setAdding] = useState(false);
  const closeEditor = () => {
    setEditing(null);
    setAdding(false);
  };
  const saveDemo = (draft: DemoProduct) => {
    setCatalog((current) => editing ? current.map((item) => item.id === editing.id ? { ...draft, id: editing.id } : item) : [...current, { ...draft, id: Math.max(...current.map((item) => item.id), 0) + 1 }]);
    onNotice("Alteração simulada com sucesso.");
    setTimeout(() => onNotice(""), 3000);
    closeEditor();
  };
  return (
    <>
      <PageTitle
        title="Produtos"
        text="Catálogo demonstrativo com criação e edição simuladas."
        action={
          <button onClick={() => setAdding(true)} className="primary-button">
            <Plus className="mr-2 h-4 w-4" /> Novo produto
          </button>
        }
      />
      <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">
        {catalog.map((product) => (
          <article
            key={product.id}
            className="flex gap-4 rounded-3xl border bg-card p-4 shadow-[var(--shadow-card)]"
          >
            <img src={asset(product.image)} className="h-24 w-24 rounded-2xl object-cover" />
            <div className="min-w-0 flex-1">
              <p className="line-clamp-2 font-bold text-primary">{product.title}</p>
              <p className="mt-1 text-sm text-muted-foreground">{product.category}</p>
              <p className="mt-2 font-bold text-accent">{money(product.price)}</p>
              <div className="mt-2 flex gap-3"><button onClick={() => setEditing(product)} className="inline-flex items-center text-sm font-bold text-primary"><Edit3 className="mr-1.5 h-3.5 w-3.5" /> Editar</button><button onClick={() => setCatalog((current) => current.filter((item) => item.id !== product.id))} className="inline-flex items-center text-sm font-bold text-destructive"><Trash2 className="mr-1.5 h-3.5 w-3.5" /> Excluir</button></div>
            </div>
          </article>
        ))}
      </div>
      {(editing !== null || adding) && (
        <Modal onClose={closeEditor} title={editing ? "Editar produto" : "Novo produto"}>
          <DemoProductForm product={editing} onSave={saveDemo} />
        </Modal>
      )}
    </>
  );
}
function DemoProductForm({ product, onSave }: { product: DemoProduct | null; onSave: (product: DemoProduct) => void }) { const [title, setTitle] = useState(product?.title || "Combo 4 Ímãs Demo"); const [category, setCategory] = useState(product?.category || "Combo Personalizado"); const [price, setPrice] = useState(product?.price || 39.9); const [photoCount, setPhotoCount] = useState(product?.photoCount || 4); const [description, setDescription] = useState(product?.description || "Descrição fictícia do produto demonstrativo."); const submit = () => onSave({ id: product?.id || 0, title, handle: product?.handle || title.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, ""), category, description, price: Number(price), image: product?.image || "products/prod-combo6.jpg", photoCount: Number(photoCount), tags: product?.tags || ["demo"] }); return <div className="space-y-4"><label className="block"><span className="text-sm font-bold">Nome</span><input className="demo-input mt-1" value={title} onChange={(event) => setTitle(event.target.value)} /></label><label className="block"><span className="text-sm font-bold">Categoria</span><input className="demo-input mt-1" value={category} onChange={(event) => setCategory(event.target.value)} /></label><div className="grid grid-cols-2 gap-3"><label className="block"><span className="text-sm font-bold">Preço</span><input type="number" className="demo-input mt-1" value={price} onChange={(event) => setPrice(Number(event.target.value))} /></label><label className="block"><span className="text-sm font-bold">Fotos exigidas</span><input type="number" className="demo-input mt-1" value={photoCount} onChange={(event) => setPhotoCount(Number(event.target.value))} /></label></div><label className="block"><span className="text-sm font-bold">Descrição</span><textarea className="demo-input mt-1 min-h-24" value={description} onChange={(event) => setDescription(event.target.value)} /></label><label className="block cursor-pointer rounded-2xl border border-dashed p-4 text-center text-sm text-muted-foreground transition hover:border-accent"><Upload className="mx-auto mb-2 h-5 w-5" /> Selecionar imagem fictícia<input type="file" accept="image/*" className="sr-only" /></label><button onClick={submit} className="primary-button w-full"><Save className="mr-2 h-4 w-4" /> Salvar na demonstração</button></div>; }
function CustomersView() { return <><PageTitle title="Clientes" text="Histórico fictício de compradores e pedidos." /><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Stat label="Clientes" value="39" icon={Users} tone="accent" /><Stat label="Recorrentes" value="8" icon={Heart} tone="teal" /><Stat label="Ticket médio" value="R$ 86,40" icon={Wallet} tone="lilac" /><Stat label="Novos este mês" value="14" icon={Sparkles} tone="yellow" /></div><div className="mt-5"><Panel title="Lista de clientes"><div className="overflow-x-auto"><table className="w-full min-w-[650px] text-sm"><thead><tr className="border-b text-left text-xs uppercase text-muted-foreground"><th className="py-3">Cliente</th><th>WhatsApp</th><th>Pedidos</th><th className="text-right">Total gasto</th></tr></thead><tbody>{customers.map((c) => <tr key={c.email} className="border-b last:border-0"><td className="py-3"><p className="font-bold">{c.name}</p><p className="text-xs text-muted-foreground">{c.email}</p></td><td>{c.phone}</td><td>{c.orders}</td><td className="text-right font-bold">{money(c.spent)}</td></tr>)}</tbody></table></div></Panel></div></>; }
function AnalyticsView() { return <><PageTitle title="Análise de acessos" text="Comportamento fictício dos visitantes nos últimos 30 dias." /><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-5"><Stat label="Visitantes" value="1.284" icon={Users} tone="accent" /><Stat label="Sessões" value="1.672" icon={Activity} tone="teal" /><Stat label="Páginas vistas" value="4.830" icon={Eye} tone="lilac" /><Stat label="Tempo médio" value="3min 42s" icon={Clock3} tone="yellow" /><Stat label="Conversão" value="3,7%" icon={Gauge} tone="accent" /></div><div className="mt-5"><Panel title="Visitantes por dia"><MiniChart /></Panel></div><div className="mt-5 grid gap-5 lg:grid-cols-3"><Ranking title="Páginas mais acessadas" items={[["Página inicial",1284],["Combo 12 Ímãs",718],["Ímã personalizado",604],["Combo Polaroid",381]]} /><Ranking title="Origem dos acessos" items={[["Google",672],["Instagram",438],["Acesso direto",311],["WhatsApp",251]]} /><Ranking title="Dispositivos" items={[["Celular",1087],["Computador",492],["Tablet",93]]} /></div></>; }
function SeoView({ onNotice }: { onNotice: (s: string) => void }) {
  const [title, setTitle] = useState("Foto Ímãs Store — Ímãs personalizados com suas fotos");
  const [description, setDescription] = useState("Crie ímãs personalizados com suas fotos e receba em todo o Brasil.");
  const [keywords, setKeywords] = useState(["ímã personalizado", "ímã com foto", "presente personalizado"]);
  const [keyword, setKeyword] = useState("");
  const [extraPages, setExtraPages] = useState<string[]>(["Combo 12 Ímãs Personalizados", "Ímã Personalizado com Foto"]);
  const save = () => { onNotice("SEO fictício salvo com sucesso."); setTimeout(() => onNotice(""), 3000); };
  return <><PageTitle title="SEO" text="Editor demonstrativo de títulos, descrições, páginas e palavras-chave." action={<div className="flex flex-wrap gap-2"><button onClick={() => setExtraPages((current) => [...current, `Nova página SEO ${current.length + 1}`])} className="secondary-button"><Plus className="mr-2 h-4 w-4" /> Adicionar página</button><button onClick={save} className="primary-button"><Save className="mr-2 h-4 w-4" /> Salvar SEO</button></div>} /><div className="grid gap-5 xl:grid-cols-2"><Panel title="Página inicial"><div className="space-y-4"><label className="block"><span className="text-sm font-bold">Título no Google</span><input className="demo-input mt-1" value={title} onChange={(event) => setTitle(event.target.value)} /><span className="mt-1 block text-right text-xs text-muted-foreground">{title.length}/60</span></label><label className="block"><span className="text-sm font-bold">Descrição no Google</span><textarea className="demo-input mt-1 min-h-24" value={description} onChange={(event) => setDescription(event.target.value)} /><span className="mt-1 block text-right text-xs text-muted-foreground">{description.length}/160</span></label><label className="block"><span className="text-sm font-bold">Palavras-chave</span><div className="mt-1 flex gap-2"><input className="demo-input" value={keyword} onChange={(event) => setKeyword(event.target.value)} placeholder="Adicionar termo" /><button onClick={() => { if (keyword.trim()) { setKeywords((old) => [...old, keyword.trim()]); setKeyword(""); } }} className="secondary-button"><Plus className="h-4 w-4" /></button></div></label><div className="flex flex-wrap gap-2">{keywords.map((value, index) => <span key={`${value}-${index}`} className="inline-flex items-center gap-1 rounded-full bg-secondary px-3 py-1.5 text-xs font-bold">{value}<button onClick={() => setKeywords((old) => old.filter((_, itemIndex) => index !== itemIndex))}><X className="h-3 w-3" /></button></span>)}</div></div></Panel><Panel title="Prévia no Google"><div className="rounded-2xl border bg-white p-5"><p className="text-sm text-[#202124]">fotoimasstore.com.br</p><p className="mt-1 text-xl text-[#1a0dab]">{title || "Título da página"}</p><p className="mt-1 text-sm text-gray-600">{description || "Descrição da página para os resultados de busca."}</p></div><p className="mb-2 mt-5 text-sm font-bold text-primary">Páginas configuradas</p><div className="space-y-3">{extraPages.map((page, index) => <div key={`${page}-${index}`} className="flex items-center gap-3 rounded-2xl bg-secondary/40 p-3"><Search className="h-4 w-4 text-accent" /><input value={page} onChange={(event) => setExtraPages((current) => current.map((item, itemIndex) => itemIndex === index ? event.target.value : item))} className="min-w-0 flex-1 bg-transparent text-sm font-bold outline-none" /><CheckCircle2 className="h-4 w-4 text-teal" /><button onClick={() => setExtraPages((current) => current.filter((_, itemIndex) => itemIndex !== index))}><Trash2 className="h-4 w-4 text-destructive" /></button></div>)}</div></Panel></div></>;
}
function SettingsView() { return <><PageTitle title="Configurações" text="Integrações exibidas somente para apresentação visual." /><div className="grid gap-5 lg:grid-cols-2"><Integration icon={Wallet} title="Mercado Pago" text="Checkout, Pix, boleto e cartão" /><Integration icon={Truck} title="Melhor Envio" text="Cálculo de frete e rastreamento" /><Integration icon={Globe2} title="Domínio da loja" text="fotoimasstore.com.br" /><Integration icon={ShieldCheck} title="Segurança" text="Sessão administrativa protegida" /></div><div className="mt-5 rounded-3xl border border-yellow/50 bg-yellow/15 p-5"><p className="font-bold text-primary">Modo demonstração</p><p className="mt-1 text-sm text-muted-foreground">Nenhuma credencial, token ou integração real está presente neste repositório.</p></div></>; }

function Integration({ icon: Icon, title, text }: { icon: typeof Wallet; title: string; text: string }) { return <div className="rounded-3xl border bg-card p-5 shadow-[var(--shadow-card)]"><div className="flex items-start gap-4"><span className="flex h-11 w-11 items-center justify-center rounded-2xl bg-accent/15 text-accent"><Icon className="h-5 w-5" /></span><div className="flex-1"><p className="font-display text-lg font-bold text-primary">{title}</p><p className="text-sm text-muted-foreground">{text}</p></div><span className="rounded-full bg-teal/20 px-3 py-1 text-xs font-bold text-teal-foreground">Conectado · demo</span></div><div className="mt-4 rounded-xl bg-secondary/50 px-3 py-2 font-mono text-xs text-muted-foreground">•••••••••••• DEMO</div></div>; }
function Stat({ label, value, icon: Icon, tone, hint }: { label: string; value: string; icon: typeof Users; tone: "accent"|"teal"|"lilac"|"yellow"; hint?: string }) { const tones = { accent:"bg-accent/15 text-accent", teal:"bg-teal/25 text-teal-foreground", lilac:"bg-lilac/25 text-lilac-foreground", yellow:"bg-yellow/30 text-yellow-foreground" }; return <div className="rounded-3xl border bg-card p-5 shadow-[var(--shadow-card)]"><span className={`flex h-10 w-10 items-center justify-center rounded-2xl ${tones[tone]}`}><Icon className="h-5 w-5" /></span><p className="mt-4 text-sm font-bold text-muted-foreground">{label}</p><p className="font-display text-2xl font-bold text-primary">{value}</p>{hint && <p className="mt-1 text-xs text-muted-foreground">{hint}</p>}</div>; }
function Panel({ title, children }: { title: string; children: ReactNode }) { return <section className="rounded-3xl border bg-card p-5 shadow-[var(--shadow-card)]"><h2 className="mb-5 font-display text-lg font-bold text-primary">{title}</h2>{children}</section>; }
function MiniChart() { const max = Math.max(...visitorsByDay.map((d) => d.views)); return <div><div className="flex h-56 items-end gap-3 border-b border-l px-3 pt-5">{visitorsByDay.map((d) => <div key={d.day} className="flex h-full flex-1 flex-col justify-end gap-1"><div className="w-full rounded-t-xl bg-accent/35 transition hover:bg-accent" style={{ height: `${(d.views/max)*100}%` }} title={`${d.views} visualizações`} /></div>)}</div><div className="mt-2 flex gap-3 pl-3">{visitorsByDay.map((d) => <span key={d.day} className="flex-1 text-center text-[10px] text-muted-foreground">{d.day}</span>)}</div></div>; }
function Ranking({ title, items }: { title: string; items: (string|number)[][] }) { return <Panel title={title}><div className="space-y-3">{items.map(([name,value],i) => <div key={String(name)} className="flex items-center gap-3"><span className="flex h-7 w-7 items-center justify-center rounded-full bg-secondary text-xs font-bold">{i+1}</span><span className="min-w-0 flex-1 truncate text-sm font-bold">{name}</span><span className="text-sm text-muted-foreground">{value}</span></div>)}</div></Panel>; }
function Status({ value }: { value: string }) { const good = ["Pago","Entregue","Enviado"].includes(value); return <span className={`rounded-full px-2.5 py-1 text-xs font-bold ${good ? "bg-teal/20 text-teal-foreground" : value === "Pendente" || value === "Aguardando" ? "bg-yellow/25 text-yellow-foreground" : "bg-lilac/20 text-lilac-foreground"}`}>{value}</span>; }
function FormField({ label, value }: { label: string; value: string }) { return <label className="block"><span className="text-sm font-bold">{label}</span><input className="demo-input mt-1" defaultValue={value} /></label>; }
function Benefit({ icon: Icon, title, text }: { icon: typeof ImageIcon; title: string; text: string }) { return <div className="flex items-center gap-4 rounded-3xl border bg-card p-5 shadow-[var(--shadow-card)]"><span className="flex h-11 w-11 items-center justify-center rounded-2xl bg-accent/15 text-accent"><Icon className="h-5 w-5" /></span><div><h3 className="font-display font-bold text-primary">{title}</h3><p className="text-sm text-muted-foreground">{text}</p></div></div>; }
function MenuItem({ icon: Icon, label, onClick, featured }: { icon: typeof Home; label: string; onClick: () => void; featured?: boolean }) { return <button onClick={onClick} className={`flex w-full items-center gap-3 rounded-2xl px-4 py-3.5 text-left font-bold ${featured ? "bg-accent text-white" : "hover:bg-secondary"}`}><Icon className="h-5 w-5" />{label}</button>; }
function Empty({ icon: Icon, title, text }: { icon: typeof ShoppingBag; title: string; text: string }) { return <div className="py-16 text-center"><Icon className="mx-auto h-10 w-10 text-muted-foreground" /><p className="mt-3 font-bold text-primary">{title}</p><p className="mt-1 text-sm text-muted-foreground">{text}</p></div>; }
function Overlay({ children, onClose, side = "right" }: { children: ReactNode; onClose: () => void; side?: "left"|"right" }) { return <div className="overlay-enter fixed inset-0 z-[60] bg-black/55" onMouseDown={onClose}><aside onMouseDown={(e) => e.stopPropagation()} className={`drawer-enter absolute inset-y-0 ${side === "right" ? "right-0" : "left-0"} w-[88%] max-w-md bg-background shadow-2xl`} style={{ transformOrigin: side === "right" ? "right" : "left" }}><button onClick={onClose} className="absolute right-4 top-4 z-10 rounded-full bg-secondary p-2 transition hover:rotate-90"><X className="h-4 w-4" /></button>{children}</aside></div>; }
function Modal({ title, children, onClose }: { title: string; children: ReactNode; onClose: () => void }) { return <div className="overlay-enter fixed inset-0 z-[70] flex items-center justify-center bg-black/55 p-4" onMouseDown={onClose}><div onMouseDown={(e) => e.stopPropagation()} className="modal-enter relative max-h-[94vh] w-full max-w-3xl overflow-y-auto rounded-3xl bg-background p-6 shadow-2xl"><div className="mb-5 flex items-center justify-between"><h2 className="font-display text-2xl font-bold text-primary">{title}</h2><button onClick={onClose} className="icon-button h-9 w-9"><X className="h-5 w-5" /></button></div>{children}</div></div>; }
